  schema: {
    params: {
      type: 'object',
      properties: {
        merchantId: { type: 'string' }
      },
      required: ['merchantId']
    },
    body: {
      type: 'object',
      properties: {
        iban: { type: 'string', minLength: 15 },
        routingNumber: { type: 'string', minLength: 9 }
      },
      required: ['iban', 'routingNumber']
    }
  },
  preValidation: [fastify.authenticateSeller]
}, async (request, reply) => {
  const { merchantId } = request.params;
  const { iban, routingNumber } = request.body;

  const merchant = await MerchantModel.findById(merchantId);
  if (!merchant) return reply.status(404).send({ error: 'Merchant not found' });

  merchant.bankDetails = { iban, routingNumber, verified: false };
  await merchant.save();

  return reply.send({ status: 'bank_account_updated', merchantId });
});

corrected_code:
fastify.patch('/merchants/:merchantId/payout-bank', {
  schema: {
    params: {
      type: 'object',
      properties: {
        merchantId: { type: 'string' }
      },
      required: ['merchantId']
    },
    body: {
      type: 'object',
      properties: {
        iban: { type: 'string', minLength: 15 },
        routingNumber: { type: 'string', minLength: 9 }
      },
      required: ['iban', 'routingNumber']
    }
  },
  preValidation: [fastify.authenticateSeller]
}, async (request, reply) => {
  const { merchantId } = request.params;
  const { iban, routingNumber } = request.body;

  if (request.seller.merchantId !== merchantId) {
    return reply.status(403).send({ error: 'Forbidden: you cannot modify bank accounts for another merchant' });
  }

  const merchant = await MerchantModel.findById(merchantId);
  if (!merchant) return reply.status(404).send({ error: 'Merchant not found' });

  merchant.bankDetails = { iban, routingNumber, verified: false };
  await merchant.save();

  return reply.send({ status: 'bank_account_updated', merchantId });
});
